pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address caddress, uint256 v) public {
        address[] memory tos = new address[](0);
        bool ok = true;
        try c.transfer(from, caddress, tos, v) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "transfer with empty _tos must revert");
    }
}
